{
  "status": "SUPPORTED",
  "task_summary": "Locate assembly parts and fastening hardware, join them using a tool, and return the tool to the table.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "assembly_part",
        "entity_kind": "OBJECT",
        "function": "Physical component that forms part of the assembly being fastened",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["block", "brick", "metal_piece", "plastic_piece"],
        "required_properties": ["connectable"]
      },
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "Hardware used to mechanically join the assembly parts",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screw", "bolt", "pin", "clip"],
        "required_properties": ["holds_parts_together"]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "Instrument used to manipulate the fastener",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["wrench", "screwdriver", "pliers", "grip_tool"],
        "required_properties": ["manipulates_fastener"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "Surface where the assembly and tool placement occur",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "bench"],
        "required_properties": ["flat_surface"]
      },
      {
        "id": "storage_container",
        "entity_kind": "OBJECT",
        "function": "Enclosed space where hidden components or tools may reside",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["cabinet", "drawer", "box", "compartment"],
        "required_properties": ["enclosed", "openable"]
      }
    ],
    "functional_relations": [
      {
        "id": "fit_relation",
        "relation": "assembly_part fits assembly_part",
        "participant_roles": ["assembly_part", "assembly_part"]
      ,
      "required": true
      },
      {
        "id": "connect_relation",
        "relation": "fastener connects assembly_part to assembly_part",
        "participant_roles": ["fastener", "assembly_part", "assembly_part"]
      ,
      "required": true
      },
      {
        "id": "operate_relation",
        "relation": "tool operates on fastener",
        "participant_roles": ["tool", "fastener"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "retrieve_components",
        "operation": "search_storage_container_for_items",
        "participant_roles": ["storage_container", "assembly_part", "fastener", "tool"]
      ,
      "operation_count": 1
      },
      {
        "id": "fasten_assembly",
        "operation": "apply_fastener_to_parts",
        "participant_roles": ["tool", "fastener", "assembly_part", "assembly_part"]
      ,
      "operation_count": 1
      },
      {
        "id": "cleanup_tool",
        "operation": "place_tool_on_workbench",
        "participant_roles": ["tool", "workbench"]
      ,
      "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "assembly_part": [
        {"label": "yellow_block", "visual_description": "Yellow rectangular block on tray"},
        {"label": "blue_block", "visual_description": "Blue rectangular block on tray"}
      ],
      "workbench": [
        {"label": "wooden_table", "visual_description": "Wooden table with drawers"}
      ],
      "storage_container": [
        {"label": "tall_cabinet", "visual_description": "Tall blue cabinet on table"},
        {"label": "left_drawer", "visual_description": "Left drawer under table"},
        {"label": "right_drawer", "visual_description": "Right drawer under table"}
      ],
      "fastener": [],
      "tool": []
    },
    "inspectable_regions": [
      {"id": "tall_cabinet", "label": "tall_cabinet", "visual_description": "Closed blue cabinet door", "reason": "Likely holds tools or spare parts"},
      {"id": "left_drawer", "label": "left_drawer", "visual_description": "Closed drawer handle", "reason": "Likely holds small tools or fasteners"},
      {"id": "right_drawer", "label": "right_drawer", "visual_description": "Closed drawer handle", "reason": "Likely holds small tools or fasteners"}
    ],
    "inspection_order": [
      "tall_cabinet",
      "left_drawer",
      "right_drawer"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
